  { id: 'W', name: 'Белые', action: 'Показывайте жестами', short: 'Жесты', icon: 'taste', example: 'А теперь покажите штопор.', rule: 'Пускайте в ход мимику и воображаемые предметы. Без слов и звуков.' },
  { id: 'P', name: 'Розовые', action: 'Соединяйте оба способа', short: 'Вместе', icon: 'game', example: 'Можно и сказать, и показать.', rule: 'Слова и жесты работают вместе. Сам ответ и однокоренные слова по-прежнему под запретом.' },
